async function loadEcosystem(){
 const ids=["ecoKpis","ecoUsers","ecoCoins","ecoReports","ecoPromos","ecoActivity"];
 ids.forEach(id=>{if($(id))$(id).innerHTML='<div class="ent-empty">Loading…</div>'});
 const jobs=[
  ["overview",()=>api("/overview")],
  ["users",()=>api("/subscriptions")],
  ["coins",()=>api("/coins/analytics")],
  ["reports",()=>api("/reports")],
  ["promos",()=>api("/promos")],
  ["activity",()=>api("/activity")]
 ];
 const out={}; await Promise.all(jobs.map(async([k,fn])=>{try{out[k]=await fn()}catch(e){out[k]={_error:e.message||"Request failed"}}}));
 const ok=k=>out[k]&&!out[k]._error;
 const statCard=(v,l)=>'<div class="ent-platform"><strong style="font-size:20px">'+esc(v??"—")+'</strong><small>'+esc(l)+'</small></div>';
 const st=out.overview?.stats||{};
 $("ecoKpis").innerHTML=ok("overview")?[
  statCard(st.users,"Registered users"),statCard(st.aiRequests,"AI requests"),statCard(st.openReports,"Open support reports"),statCard(st.activePromoCodes,"Active promo codes")
 ].join(""):'<div class="ent-empty">Overview unavailable: '+esc(out.overview?._error)+'</div>';
 if(ok("users")){
  const rows=out.users.users||[];
  $("ecoUsers").innerHTML=rows.map(u=>'<div class="ent-item"><div><strong>'+esc(u.name||"Unnamed user")+' · #'+esc(u.id)+'</strong><small>'+esc(u.email)+' · '+esc(u.plan)+' · '+esc(u.is_active?"ACTIVE":"SUSPENDED")+'</small><small>Expires: '+esc(u.plan_expires_at||"—")+' · '+esc(u.balance)+' BC</small></div><span class="ent-pill">'+esc(u.plan)+'</span></div>').join("")||'<div class="ent-empty">No user records returned.</div>';
 }else $("ecoUsers").innerHTML='<div class="ent-empty">Users unavailable: '+esc(out.users?._error)+'</div>';
 if(ok("coins")){
  const q=out.coins.summary||{};
  $("ecoCoins").innerHTML=[["Wallets",q.wallet_count],["Circulating balance",q.circulating_balance+" BC"],["Total granted",q.total_granted+" BC"],["Expired balance",q.expired_balance+" BC"],["Total spent",q.total_spent+" BC"]].map(x=>'<div class="ent-item"><strong>'+esc(x[0])+'</strong><span class="ent-pill">'+esc(x[1]??"—")+'</span></div>').join("")+'<p class="ent-sub">Top service usage</p>'+(out.coins.services||[]).map(x=>'<div class="ent-item"><strong>'+esc(x.service_type)+'</strong><span class="ent-pill">'+esc(x.operations)+' · '+esc(x.coins)+' BC</span></div>').join("");
 }else $("ecoCoins").innerHTML='<div class="ent-empty">Coin analytics unavailable: '+esc(out.coins?._error)+'</div>';
 if(ok("reports")){
  const rows=out.reports.reports||[];
  $("ecoReports").innerHTML=rows.slice(0,30).map(r=>'<div class="ent-item"><div><strong>#'+esc(r.id)+' · '+esc(r.subject)+'</strong><small>'+esc(r.name||r.email||"User")+' · '+esc(r.created_at)+'</small><small>'+esc(r.message).slice(0,180)+'</small></div><span class="ent-pill">'+esc(r.status)+'</span></div>').join("")||'<div class="ent-empty">No support reports.</div>';
 }else $("ecoReports").innerHTML='<div class="ent-empty">Support unavailable: '+esc(out.reports?._error)+'</div>';
 if(ok("promos")){
  const rows=out.promos.codes||[];
  $("ecoPromos").innerHTML=rows.map(p=>'<div class="ent-item"><div><strong>'+esc(p.code)+'</strong><small>'+esc(p.code_type)+' · '+esc(p.plan||p.coin_amount||p.discount_percent||"")+'</small><small>'+esc(p.uses_count)+' / '+esc(p.max_uses??"∞")+' uses · expires '+esc(p.expires_at||"never")+'</small></div><span class="ent-pill">'+esc(p.is_active?"ACTIVE":"DISABLED")+'</span></div>').join("")||'<div class="ent-empty">No promo codes.</div>';
 }else $("ecoPromos").innerHTML='<div class="ent-empty">Promo codes unavailable: '+esc(out.promos?._error)+'</div>';
 if(ok("activity")){
  const rows=out.activity.activity||[];
  $("ecoActivity").innerHTML=rows.slice(0,30).map(a=>'<div class="ent-item"><div><strong>'+esc(a.action)+'</strong><small>'+esc(a.username||"System")+' · '+esc(a.created_at)+'</small><small>'+esc(a.details||"")+'</small></div><span class="ent-pill">'+esc(a.source||"ADMIN")+'</span></div>').join("")||'<div class="ent-empty">No recent activity.</div>';
 }else $("ecoActivity").innerHTML='<div class="ent-empty">Activity unavailable: '+esc(out.activity?._error)+'</div>';
 const failures=jobs.filter(([k])=>!ok(k)).map(([k])=>k);
 $("ecoUpdated").textContent="Last refreshed: "+new Date().toLocaleString()+" · "+(jobs.length-failures.length)+"/"+jobs.length+" data services connected"+(failures.length?" · Unavailable: "+failures.join(", "):"");
}
function updateEcosystemPromoFields(){const t=$("ecoPromoType")?.value||"SUBSCRIPTION";$("ecoPromoPlan").disabled=t!=="SUBSCRIPTION";$("ecoPromoDays").disabled=t!=="SUBSCRIPTION";$("ecoPromoCoins").disabled=t!=="COINS";$("ecoPromoDiscount").disabled=t!=="DISCOUNT"}
async function applyEcosystemSubscription(e){e.preventDefault();const userId=Number($("ecoSubUser").value),action=$("ecoSubAction").value,plan=$("ecoSubPlan").value,days=Number($("ecoSubDays").value),reason=$("ecoSubReason").value.trim();if(!userId||!reason){stat("ecoSubStatus","Choose a user and enter a reason.","error");return}if(action!=="CANCEL"&&(!Number.isSafeInteger(days)||days<1||days>3650)){stat("ecoSubStatus","Duration must be between 1 and 3650 days.","error");return}const user=ecosystemUsers.find(x=>Number(x.id)===userId);if(!confirm("Confirm "+action+" subscription for "+(user?.email||("user #"+userId))+"?"))return;const b=e.currentTarget.querySelector("button");b.disabled=true;stat("ecoSubStatus","Applying subscription update…");try{const d=await post("/subscriptions/adjust",{user_id:userId,action,plan,days,reason});if(!d?.success||!d.user)throw Error("Server did not confirm the subscription update.");stat("ecoSubStatus","Updated successfully: "+d.user.plan+" · "+(d.user.plan_expires_at||"No expiry"),"ok");$("ecoSubReason").value="";await loadEcosystem()}catch(x){stat("ecoSubStatus",x.message||"Subscription update failed.","error")}finally{b.disabled=false}}
async function applyEcosystemCoins(e){e.preventDefault();const userId=Number($("ecoCoinUser").value),action=$("ecoCoinAction").value,amount=Number($("ecoCoinAmount").value),description=$("ecoCoinReason").value.trim();if(!userId||!Number.isSafeInteger(amount)||amount<1||amount>100000000||!description){stat("ecoCoinStatus","Choose a user, valid whole-number amount and reason.","error");return}const user=ecosystemUsers.find(x=>Number(x.id)===userId);if(!confirm("Confirm "+(action==="CREDIT"?"adding ":"deducting ")+amount+" BERU Coins "+(action==="CREDIT"?"to ":"from ")+(user?.email||("user #"+userId))+"?"))return;const b=e.currentTarget.querySelector("button");b.disabled=true;stat("ecoCoinStatus","Applying wallet adjustment…");try{const d=await post("/coins/adjust",{user_id:userId,action,amount,description});if(!d?.success||Number(d.balance)<0)throw Error("Server did not confirm the wallet adjustment.");stat("ecoCoinStatus","Wallet updated. New balance: "+d.balance+" BC","ok");$("ecoCoinAmount").value="";$("ecoCoinReason").value="";await loadEcosystem()}catch(x){stat("ecoCoinStatus",x.message||"Wallet adjustment failed.","error")}finally{b.disabled=false}}
async function createEcosystemPromo(e){e.preventDefault();const type=$("ecoPromoType").value,code=$("ecoPromoCode").value.trim(),maxRaw=$("ecoPromoLimit").value,expiry=$("ecoPromoExpiry").value;const payload={code,code_type:type,plan:$("ecoPromoPlan").value,duration_days:type==="SUBSCRIPTION"?Number($("ecoPromoDays").value):null,coin_amount:type==="COINS"?Number($("ecoPromoCoins").value):null,discount_percent:type==="DISCOUNT"?Number($("ecoPromoDiscount").value):null,max_uses:maxRaw?Number(maxRaw):null,expires_at:expiry?new Date(expiry).toISOString():null};if(type==="SUBSCRIPTION"&&(!Number.isInteger(payload.duration_days)||payload.duration_days<1||payload.duration_days>3650)){stat("ecoPromoStatus","Enter a valid subscription duration.","error");return}if(type==="COINS"&&(!Number.isSafeInteger(payload.coin_amount)||payload.coin_amount<1)){stat("ecoPromoStatus","Enter a valid coin reward.","error");return}if(type==="DISCOUNT"&&(!Number.isInteger(payload.discount_percent)||payload.discount_percent<1||payload.discount_percent>100)){stat("ecoPromoStatus","Enter a discount from 1 to 100%.","error");return}if(!confirm("Create this "+type+" promo code for redemption in BERU AI?"))return;const b=e.currentTarget.querySelector("button");b.disabled=true;stat("ecoPromoStatus","Creating promo code…");try{const d=await post("/promos",payload);if(!d?.success||!d.code)throw Error("Server did not confirm promo code creation.");stat("ecoPromoStatus","Promo code created: "+d.code,"ok");$("ecoPromoForm").reset();updateEcosystemPromoFields();await loadEcosystem()}catch(x){stat("ecoPromoStatus",x.message||"Promo creation failed.","error")}finally{b.disabled=false}}
function open(id,label){if(chatTimer){clearInterval(chatTimer);chatTimer=null}if(digitalTimer){clearInterval(digitalTimer);digitalTimer=null}document.querySelectorAll('[id^="view-"]').forEach(x=>x.classList.add("hidden"));$("view-"+id).classList.remove("hidden");document.querySelectorAll(".nav").forEach(x=>x.classList.toggle("active",x.dataset.ent===id));$("crumb").textContent=label;if(id==="ecosystem")loadEcosystem();if(id==="amani")loadAmani();if(id==="digital"){loadDigital();digitalTimer=setInterval(()=>{if(!document.hidden)loadDigital()},30000)}if(id==="enterprise-chat"){loadChannels();loadMeetings();chatTimer=setInterval(()=>{if(!document.hidden){loadMessages();loadChannels()}},7000)}if(id==="enterprise-people")loadPeople();if(id==="enterprise-tasks"){loadTasks();loadDepartments()}if(id==="enterprise-social")loadSocial();if(id==="enterprise-gmail")loadGmailStatus()}
async function loadProfile(){const d=await api("/enterprise/profile");profile=d.profile;document.querySelectorAll('[data-ent="digital"]').forEach(n=>n.classList.toggle("hidden",profile.role!=="OWNER"));document.querySelectorAll('[data-ent="ecosystem"]').forEach(n=>n.classList.toggle("hidden",profile.role!=="OWNER"));document.querySelectorAll('[data-ent="amani"]').forEach(n=>n.classList.toggle("hidden",profile.role!=="OWNER"));document.querySelectorAll('[data-ent="enterprise-gmail"]').forEach(n=>n.classList.toggle("hidden",!["OWNER","VICE_OWNER","ADMIN","SUPPORT"].includes(profile.role)));$("entDisplayName").value=profile.display_name||"";$("entAvatarUrl").value=profile.avatar_url||"";$("entMyRole").textContent=profile.role;$("adminIdentity").textContent=profile.display_name||profile.username;$("adminAvatar").textContent=(profile.display_name||"B").slice(0,1).toUpperCase();if(profile.role!=="OWNER"){$("entMemberCard").classList.add("hidden");$("entDepartmentCard").classList.add("hidden")}if(!["OWNER","VICE_OWNER","ADMIN"].includes(profile.role))$("entCreateTaskCard").classList.add("hidden")}
async function saveProfile(e){e.preventDefault();try{await post("/enterprise/profile",{display_name:$("entDisplayName").value,avatar_url:$("entAvatarUrl").value});stat("entProfileStatus","Profile saved.","ok");await loadProfile()}catch(x){stat("entProfileStatus",x.message,"error")}}
async function loadPeople(){try{await loadProfile();if(["OWNER","VICE_OWNER","ADMIN"].includes(profile.role)){const d=await api("/enterprise/team");members=d.members||[];const agentData=await api("/enterprise/system-agents");const agents=agentData.agents||[];$("entMembers").innerHTML=members.map(m=>'<div class="ent-item"><div><strong>'+esc(m.display_name)+'</strong><small>'+esc(m.rank_title||m.role)+' · '+esc(m.department||"Unassigned")+'</small></div><span class="ent-pill">'+(m.is_active?"ACTIVE":"INACTIVE")+'</span></div>').join("")||'<div class="ent-empty">No staff.</div>';$("entSystemAgents").innerHTML=agents.map(a=>'<div class="ent-item"><div><strong>'+esc(a.display_name)+'</strong><small>'+esc(a.rank_title)+' · '+esc(a.department)+'</small><small>'+esc(a.description)+'</small></div><span class="ent-pill">'+esc(a.status)+'</span></div>').join("")||'<div class="ent-empty">No system agents registered.</div>';$("entMemberId").innerHTML='<option value="">Select member</option>'+members.map(m=>'<option value="'+m.id+'">'+esc(m.display_name)+'</option>').join("");$("entTaskAssignee").innerHTML='<option value="">Select assignee</option>'+members.filter(m=>m.is_active).map(m=>'<option value="'+m.id+'">'+esc(m.display_name)+'</option>').join("")}else{$("entMembers").innerHTML='<div class="ent-empty">Directory is visible to leadership.</div>';$("entSystemAgents").innerHTML='<div class="ent-empty">Leadership access required.</div>';$("entMemberCard").classList.add("hidden")}}catch(x){$("entMembers").textContent=x.message;if($("entSystemAgents"))$("entSystemAgents").textContent=x.message}}async function saveMember(e){e.preventDefault();try{await post("/enterprise/team",{id:+$("entMemberId").value,display_name:$("entMemberName").value,department:$("entMemberDepartment").value,rank_title:$("entMemberTitle").value});stat("entMemberStatus","Identity updated.","ok");loadPeople()}catch(x){stat("entMemberStatus",x.message,"error")}}
async function loadChannels(){try{const d=await api("/enterprise/channels");channels=d.channels||[];$("entChannels").innerHTML=channels.map(c=>'<button class="ent-channel '+(active===c.id?"active":"")+'" data-channel="'+c.id+'">'+esc(c.name)+' · '+c.message_count+'</button>').join("")||'<div class="ent-empty">No channels available.</div>';if(!active&&channels.length)selectChannel(channels[0].id);else if(active)selectChannel(active)}catch(x){$("entChannels").textContent=x.message}}
async function selectChannel(id){active=id;const c=channels.find(x=>x.id===id);if(!c)return;$("entChannelTitle").textContent=c.name;$("entChannels").querySelectorAll(".ent-channel").forEach(b=>b.classList.toggle("active",+b.dataset.channel===id));loadMessages()}
async function loadMessages(){if(!active)return;try{const d=await api("/enterprise/messages?channel_id="+active);$("entMessages").innerHTML=(d.messages||[]).map(m=>'<article class="ent-message '+(m.is_ai?'ent-ai-message':'')+'"><strong>'+esc(m.display_name)+' · '+esc(m.role)+(m.is_ai?' ✦':'')+'</strong><p>'+esc(m.message)+'</p><small>'+esc(m.created_at)+(m.is_ai?' · AI-generated':'')+'</small></article>').join("")||'<div class="ent-empty">No messages yet. Start the conversation.</div>';$("entMessages").scrollTop=$("entMessages").scrollHeight}catch(x){$("entMessages").textContent=x.message}}
async function sendMessage(e){e.preventDefault();const message=$("entMessageInput").value.trim();if(!message||!active)return;const b=e.currentTarget.querySelector("button"),match=message.match(/^@(chatgpt|chatgbt)\b[\s,:-]*(.*)$/is);b.disabled=true;try{await post("/enterprise/messages",{channel_id:active,message});$("entMessageInput").value="";await loadMessages();loadChannels();if(match){const prompt=match[2].trim()||"Please join the discussion and share a helpful response.";try{await post("/enterprise/ai/chat",{channel_id:active,prompt});await loadMessages();}catch(aiError){alert(aiError.message)}}}catch(x){alert(x.message)}finally{b.disabled=false}}
async function loadMeetings(){try{const d=await api("/enterprise/meetings");$("entMeetings").innerHTML=(d.meetings||[]).map(m=>'<div class="ent-item"><div><strong>'+esc(m.title)+'</strong><small>'+esc(m.meeting_type)+' · '+esc(m.scheduled_at||"Unscheduled")+' · '+esc(m.created_by_name)+'</small></div><span class="ent-pill">'+esc(m.status)+'</span></div>').join("")||'<div class="ent-empty">No meetings scheduled.</div>'}catch(x){$("entMeetings").textContent=x.message}}
async function createMeeting(e){e.preventDefault();try{const dt=$("entMeetingDate").value;await post("/enterprise/meetings",{title:$("entMeetingTitle").value,agenda:$("entMeetingAgenda").value,meeting_type:$("entMeetingType").value,scheduled_at:dt?new Date(dt).toISOString():null});stat("entMeetingStatus","Meeting scheduled.","ok");e.currentTarget.reset();loadMeetings()}catch(x){stat("entMeetingStatus",x.message,"error")}}
async function loadDepartments(){try{const d=await api("/enterprise/departments"),rows=d.departments||[];$("entDepartments").innerHTML=rows.map(x=>'<div class="ent-item"><div><strong>'+esc(x.name)+'</strong><small>'+esc(x.description||"")+'</small></div><span class="ent-pill">'+esc(x.member_count)+' members · '+esc(x.manager_name||"No manager")+'</span></div>').join("")||'<div class="ent-empty">No departments.</div>';if(profile&&profile.role==="OWNER"){const t=await api("/enterprise/team");members=t.members||members;$("entDepartmentManager").innerHTML='<option value="">No manager assigned</option>'+members.filter(m=>m.is_active).map(m=>'<option value="'+m.id+'">'+esc(m.display_name)+'</option>').join("")}}catch(x){$("entDepartments").textContent=x.message}}
async function createDepartment(e){e.preventDefault();try{await post("/enterprise/departments",{name:$("entDepartmentName").value,description:$("entDepartmentDescription").value,manager_admin_id:$("entDepartmentManager").value?Number($("entDepartmentManager").value):null});stat("entDepartmentStatus","Department saved.","ok");e.currentTarget.reset();loadDepartments()}catch(x){stat("entDepartmentStatus",x.message,"error")}}
async function loadTasks(){try{const d=await api("/enterprise/tasks");$("entTasks").innerHTML=(d.tasks||[]).map(t=>'<div class="ent-item"><div><strong>'+esc(t.title)+'</strong><small>'+esc(t.assignee_name||"Unassigned")+' · '+esc(t.priority)+' · '+esc(t.status)+'</small><small>'+esc(t.description||"")+'</small></div><div><select class="ent-select" data-task="'+t.id+'"><option value="TODO">TODO</option><option value="IN_PROGRESS">IN_PROGRESS</option><option value="BLOCKED">BLOCKED</option><option value="DONE">DONE</option></select><button class="btn btn-ghost" data-task-save="'+t.id+'">Update</button></div></div>').join("")||'<div class="ent-empty">No tasks assigned yet.</div>';for(const t of d.tasks||[]){const s=document.querySelector('[data-task="'+t.id+'"]');if(s)s.value=t.status}}catch(x){$("entTasks").textContent=x.message}}
async function taskClick(e){const b=e.target.closest("[data-task-save]");if(!b)return;const id=+b.dataset.taskSave,s=document.querySelector('[data-task="'+id+'"]');try{await post("/enterprise/tasks/status",{id,status:s.value});loadTasks()}catch(x){alert(x.message)}}
async function createTask(e){e.preventDefault();try{const due=$("entTaskDue").value;await post("/enterprise/tasks",{title:$("entTaskTitle").value,description:$("entTaskDescription").value,assigned_to:+$("entTaskAssignee").value,priority:$("entTaskPriority").value,due_at:due?new Date(due).toISOString():null});stat("entTaskStatus","Task assigned.","ok");e.currentTarget.reset();loadTasks()}catch(x){stat("entTaskStatus",x.message,"error")}}
async function refreshSocialMetrics(){
 const b=$("entSocialRefresh");if(b){b.disabled=true;b.textContent="↻ Updating…"}
 try{await api("/enterprise/social/metrics/refresh",{method:"POST",body:JSON.stringify({platform:"YOUTUBE"})});await loadSocial()}
 catch(e){const status=$("entSocialMetricsUpdated");if(status)status.textContent=e.message}
 finally{if(b){b.disabled=false;b.textContent="↻ Refresh"}}
}
async function loadSocial(){
 const ps=[
  ["X","X","https://x.com/BERUAI01","@BERUAI01"],
  ["FACEBOOK","Facebook","https://www.facebook.com/share/1KaYDLKnng/","BERU AI"],
  ["YOUTUBE","YouTube","https://youtube.com/@beru-ai01","@beru-ai01"],
  ["TIKTOK","TikTok","https://www.tiktok.com/@beruai01","@beruai01"]
 ];
 try{
  const d=await api("/enterprise/social"),accounts=d.accounts||[],posts=d.posts||[];
  const metricRows=Array.isArray(d.metrics)?d.metrics:[];
  const metricFor=key=>metricRows.find(m=>String(m.platform||"").toUpperCase()===key)||accounts.find(a=>String(a.platform||"").toUpperCase()===key)||null;
  const readCount=(key)=>{const m=metricFor(key);const raw=key==="YOUTUBE"?(m?.subscriber_count??m?.follower_count):(m?.follower_count??m?.subscriber_count);return Number.isFinite(Number(raw))&&raw!==null&&raw!==""?Number(raw):null};
  const available=ps.map(([key])=>readCount(key)).filter(v=>v!==null);
  const total=available.length?available.reduce((a,b)=>a+b,0):null;
  $("entSocialFollowerTotal").textContent=total===null?"—":total.toLocaleString();
  $("entSocialLiveStatus").textContent=available.length?"LIVE":"WAITING FOR DATA";
  $("entSocialFollowerCards").innerHTML=ps.map(([key,label,url,handle])=>{const count=readCount(key),m=metricFor(key);const captured=m?.captured_at||m?.updated_at||null;return '<a class="ent-follower-card" href="'+url+'" target="_blank" rel="noopener noreferrer"><strong>'+label+'</strong><b>'+(count===null?"—":count.toLocaleString())+'</b><small>'+(count===null?"Awaiting verified API data":(key==="YOUTUBE"?"subscribers":"followers"))+' · '+handle+'</small></a>'}).join("");
  const stamps=metricRows.map(m=>m.captured_at).filter(Boolean).sort().reverse();
  $("entSocialMetricsUpdated").textContent=available.length
   ? "Verified platform data · last capture: "+(stamps[0]?new Date(stamps[0]).toLocaleString():"timestamp unavailable")+" · total includes "+available.length+" of 4 channels"
   : "No verified follower metrics yet. Connect authorized platform APIs to activate the counter; no estimated figures are shown.";
  $("entPlatforms").innerHTML=[["FACEBOOK","Facebook"],["INSTAGRAM","Instagram"],["X","X / Twitter"],["YOUTUBE","YouTube"],["TIKTOK","TikTok"],["LINKEDIN","LinkedIn"]].map(([key,label])=>{const rows=accounts.filter(a=>a.platform===key),connected=rows.filter(a=>a.connection_status==="CONNECTED").length;return '<div class="ent-platform"><strong>'+label+'</strong><small>'+(connected?connected+" connected":rows.length?rows.length+" registered · awaiting authorization":"Not registered")+'</small><span class="ent-pill">'+(connected?"CONNECTED":rows.length?"NOT CONNECTED":"NOT REGISTERED")+'</span></div>'}).join("");
  $("entSocialAccount").innerHTML='<option value="">Choose connected account</option>'+accounts.map(a=>'<option value="'+a.id+'">'+esc(a.platform)+' · '+esc(a.account_name)+' · '+esc(a.connection_status)+'</option>').join("");
  $("entSocialForm").querySelector("button").disabled=!accounts.length;
  $("entSocialPosts").innerHTML=posts.map(p=>{const review=["OWNER","VICE_OWNER"].includes(profile&&profile.role)&&["DRAFT","IN_REVIEW"].includes(p.post_status);return '<div class="ent-item"><div style="min-width:0"><strong>'+esc(p.platform)+' · '+esc(p.account_name)+'</strong><small>'+esc(p.post_status)+' · by '+esc(p.creator_name)+'</small><small style="white-space:pre-wrap;overflow-wrap:anywhere">'+esc(p.body)+'</small></div>'+(review?'<div class="ent-social-actions"><button class="btn" data-social="'+p.id+'" data-decision="APPROVED">Approve</button><button class="btn btn-ghost" data-social="'+p.id+'" data-decision="CHANGES_REQUESTED">Request changes</button><button class="btn btn-ghost" data-social="'+p.id+'" data-decision="REJECTED">Reject</button></div>':"")+'</div>'}).join("")||'<div class="ent-empty">No drafts yet. Platform accounts must be officially registered before drafting.</div>';
  $("entSocialCalendar").innerHTML=posts.filter(p=>p.scheduled_at).map(p=>'<div class="ent-item"><div><strong>'+esc(p.scheduled_at)+'</strong><small>'+esc(p.platform)+' · '+esc(p.body).slice(0,120)+'</small></div><span class="ent-pill">'+esc(p.post_status)+'</span></div>').join("")||'<div class="ent-empty">No scheduled posts yet. Scheduling requires official platform authorization.</div>';
  $("entSocialKpis").innerHTML=[[accounts.filter(a=>a.connection_status==="CONNECTED").length,"Connected channels"],[posts.filter(p=>p.post_status==="DRAFT").length,"Drafts"],[posts.filter(p=>p.post_status==="IN_REVIEW").length,"Awaiting review"],[posts.filter(p=>["APPROVED","SCHEDULED"].includes(p.post_status)).length,"Approved / scheduled"]].map(x=>'<div class="ent-platform"><strong style="font-size:20px">'+x[0]+'</strong><small>'+x[1]+'</small></div>').join("");
 }catch(x){$("entSocialPosts").textContent=x.message+" · Check the Social Hub database migration."}
}
async function createSocial(e){e.preventDefault();try{await post("/enterprise/social/posts",{platform_account_id:+$("entSocialAccount").value,body:$("entSocialBody").value});stat("entSocialStatus","Draft saved.","ok");$("entSocialBody").value="";loadSocial()}catch(x){stat("entSocialStatus",x.message,"error")}}
