async function loadGmailStatus(){const box=$("entGmailStatus");if(!box)return;const owner=profile?.role==="OWNER";$("entGmailOwnerPanel").classList.toggle("hidden",!owner);$("entGmailTestPanel").classList.toggle("hidden",!owner);$("entGmailComposePanel").classList.toggle("hidden",!["OWNER","VICE_OWNER","ADMIN","SUPPORT"].includes(profile?.role));box.textContent="Checking secure Gmail connection…";try{const d=await api(owner?"/oauth/gmail/status":"/gmail/availability");box.textContent=d.connected?"Connected · official sender mmzhoussem@gmail.com":"Not connected. OWNER must authorize the official mailbox.";box.className=d.connected?"ent-item":"ent-empty";if(owner){$("entGmailConnect").disabled=false;$("entGmailConnect").textContent=d.connected?"Gmail connected":"Connect owner Gmail"}}catch(e){box.textContent=e.message||"Gmail status unavailable";box.className="ent-empty";if(owner)$("entGmailConnect").disabled=false}}

async function connectGmail(){if(!profile||profile.role!=="OWNER"){stat("entGmailActionStatus","Only OWNER can connect the central mailbox.","error");return}const b=$("entGmailConnect");b.disabled=true;stat("entGmailActionStatus","Opening Google authorization…");try{const d=await post("/oauth/gmail/start",{});if(!d?.url)throw Error("Google authorization URL was not returned.");location.href=d.url}catch(e){stat("entGmailActionStatus",e.message||"Gmail connection could not start.","error");b.disabled=false}}
async function sendAdminGmail(e){e.preventDefault();const role=profile?.role;if(!["OWNER","VICE_OWNER","ADMIN","SUPPORT"].includes(role)){stat("entGmailComposeStatus","Your role is not allowed to send official email.","error");return}const recipient=$("entGmailTo").value.trim().toLowerCase(),subject=$("entGmailSubject").value.trim(),message=$("entGmailMessage").value.trim();if(!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(recipient)||!subject||/[\\r\\n]/.test(subject)||!message){stat("entGmailComposeStatus","Check the recipient, subject and message.","error");return}if(!confirm("Send this email from mmzhoussem@gmail.com to "+recipient+"?"))return;const b=$("entGmailSend");b.disabled=true;stat("entGmailComposeStatus","Sending official BERU email…");try{const d=await post("/gmail/send",{recipient,subject,message});if(!d?.success)throw Error("Server did not confirm delivery.");stat("entGmailComposeStatus","Email sent successfully from mmzhoussem@gmail.com.","ok");$("entGmailComposeForm").reset()}catch(x){stat("entGmailComposeStatus",x.message||"Email could not be sent.","error")}finally{b.disabled=false}}
async function sendGmailTest(e){e.preventDefault();if(!profile||profile.role!=="OWNER"){stat("entGmailTestStatus","Only OWNER can send a test email.","error");return}const recipient=$("entGmailTestRecipient").value.trim().toLowerCase();if(!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(recipient)||!/@(gmail\\.com|googlemail\\.com)$/.test(recipient)||!$("entGmailOwnerConfirm").checked){stat("entGmailTestStatus","Enter your own Gmail address and confirm ownership.","error");return}if(!confirm("Send a BERU Gmail test to "+recipient+"?"))return;const b=$("entGmailTestSend");b.disabled=true;stat("entGmailTestStatus","Sending test email…");try{const d=await post("/gmail/test-send",{recipient,confirm_owner_address:true});if(!d?.success)throw Error("Server did not confirm delivery.");stat("entGmailTestStatus","Test email sent to "+(d.sent_to||recipient)+". Check inbox and spam.","ok")}catch(x){stat("entGmailTestStatus",x.message||"Test email failed.","error")}finally{b.disabled=false}}
let amaniGlobalEnabled=true;
async function loadAmani(query=""){
 const ids=["amaniUserResults","amaniAssigned","amaniHistory"];ids.forEach(id=>$(id).innerHTML='<div class="ent-empty">Loading…</div>');
 try{
  const d=await api("/amani/assignments"+(query?"?query="+encodeURIComponent(query):""));
  if(!d?.success)throw Error("Could not load AMANI MODE assignments.");
  amaniGlobalEnabled=!!d.globalEnabled;
  $("amaniGlobalState").textContent=amaniGlobalEnabled?"GLOBAL ACCESS ENABLED":"GLOBAL ACCESS DISABLED";
  $("amaniGlobalState").style.color=amaniGlobalEnabled?"var(--green)":"var(--red)";
  $("amaniGlobalToggle").textContent=amaniGlobalEnabled?"Disable globally":"Enable globally";
  const assigned=d.assignments||[], users=d.users||[];
  $("amaniUserResults").innerHTML=users.map(u=>{const a=assigned.find(x=>Number(x.user_id)===Number(u.id));const enabled=!!a&&Number(a.is_enabled)===1;return '<div class="ent-item"><div><strong>'+esc(u.name||"Unnamed user")+'</strong><small>'+esc(u.email)+' · ID #'+esc(u.id)+'</small></div><button class="btn '+(enabled?'btn-ghost':'')+'" data-amani-user="'+esc(u.id)+'" data-amani-enabled="'+(enabled?'1':'0')+'" type="button">'+(enabled?'Remove AMANI MODE':'Assign AMANI MODE')+'</button></div>'}).join("")||'<div class="ent-empty">No matching accounts found.</div>';
  $("amaniAssigned").innerHTML=assigned.filter(x=>Number(x.is_enabled)===1).map(x=>'<div class="ent-item"><div><strong>'+esc(x.display_name||"Unnamed user")+'</strong><small>'+esc(x.email)+' · ID #'+esc(x.user_id)+'</small></div><span class="ent-pill">ASSIGNED</span></div>').join("")||'<div class="ent-empty">No accounts currently assigned.</div>';
  $("amaniHistory").innerHTML=(d.history||[]).map(x=>'<div class="ent-item"><div><strong>'+esc(x.action.replaceAll("_"," "))+'</strong><small>'+esc(x.email)+' · '+esc(x.created_at)+'</small></div><span class="ent-pill">ADMIN #'+esc(x.admin_id)+'</span></div>').join("")||'<div class="ent-empty">No audit events yet.</div>';
  stat("amaniSearchStatus","Loaded "+users.length+" staging accounts.","ok");
 }catch(e){stat("amaniSearchStatus",e.message||"AMANI MODE load failed.","error");ids.forEach(id=>$(id).innerHTML='<div class="ent-empty">Could not load data.</div>')}
}
async function amaniUserClick(e){const b=e.target.closest("[data-amani-user]");if(!b)return;const userId=Number(b.dataset.amaniUser),enabled=b.dataset.amaniEnabled!=="1";if(!userId)return;if(!confirm((enabled?"Assign AMANI MODE to ":"Remove AMANI MODE from ")+"this account?"))return;b.disabled=true;try{const d=await post("/amani/assign",{user_id:userId,enabled});if(!d?.success)throw Error("The server did not confirm the assignment.");stat("amaniSearchStatus",enabled?"AMANI MODE assigned successfully.":"AMANI MODE removed successfully.","ok");await loadAmani($("amaniSearch").value.trim())}catch(x){stat("amaniSearchStatus",x.message||"Assignment update failed.","error");b.disabled=false}}
async function toggleAmaniGlobal(){const enabled=!amaniGlobalEnabled;if(!confirm((enabled?"Enable":"Disable")+" AMANI MODE globally in the staging environment?"))return;const b=$("amaniGlobalToggle");b.disabled=true;try{const d=await post("/amani/global",{enabled});if(!d?.success)throw Error("The server did not confirm the global setting.");stat("amaniGlobalStatus",enabled?"Global access enabled.":"Global access disabled.","ok");await loadAmani($("amaniSearch").value.trim())}catch(e){stat("amaniGlobalStatus",e.message||"Global setting failed.","error")}finally{b.disabled=false}}
async function loadDigital(){
 let health=null,results=[];
 try{
  health=await api("/enterprise/digital/health");
  results=(health.checks||[]).map(x=>({name:x.name,group:x.group,ok:x.status==="OPERATIONAL",status:x.status,detail:x.detail}));
 }catch(e){
  results=[{name:"Digital health endpoint",group:"ADMIN ENGINE",ok:false,status:"ATTENTION",detail:String(e.message||"Health check failed").slice(0,180)}];
 }
 const ok=results.filter(x=>x.ok).length,attention=results.length-ok;
 $("digitalKpis").innerHTML=[[ok+"/"+results.length,"Live checks passed"],[attention,"Checks needing attention"],["30 sec","Auto refresh"],["OWNER","Access level"]].map(x=>'<div class="ent-platform"><strong style="font-size:20px">'+esc(x[0])+'</strong><small>'+esc(x[1])+'</small></div>').join("");
 $("digitalServices").innerHTML=results.map(x=>'<div class="ent-item"><div><strong>'+esc(x.name)+'</strong><small>'+esc(x.group)+' · '+esc(x.detail)+'</small></div><span class="ent-pill" style="background:'+(x.ok?'#123629':'#3b1b26')+';color:'+(x.ok?'#70e0b0':'#ff9aab')+'">'+esc(x.status|| (x.ok?'OPERATIONAL':'ATTENTION'))+'</span></div>').join("");
 const dbChecks=results.filter(x=>["DATABASE","TEAM","COLLABORATION","OPERATIONS","SOCIAL","BERU AI"].includes(x.group));
 $("digitalSummary").innerHTML='<div class="ent-item"><div><strong>Admin Engine</strong><small>Owner-authenticated health endpoint</small></div><span class="ent-pill">'+(health?'ONLINE':'ATTENTION')+'</span></div><div class="ent-item"><div><strong>Connected data services</strong><small>'+dbChecks.filter(x=>x.ok).length+' of '+dbChecks.length+' database checks operational</small></div><span class="ent-pill">'+(dbChecks.length&&dbChecks.every(x=>x.ok)?'HEALTHY':'REVIEW')+'</span></div><div class="ent-item"><div><strong>Diagnostic result</strong><small>'+ok+' operational · '+attention+' need attention</small></div><span class="ent-pill">'+(attention?'REVIEW':'HEALTHY')+'</span></div><div class="ent-item"><div><strong>Automation policy</strong><small>Read-only monitoring; no hidden changes or destructive actions</small></div><span class="ent-pill">SAFE MODE</span></div>';
 $("digitalCoverage").innerHTML=[["BERU ADMIN API",health?"LIVE OWNER CHECK":"CHECK FAILED"],["Admin D1 data",results.some(x=>x.group==="DATABASE"&&x.ok)?"LIVE QUERY":"ATTENTION"],["Team & collaboration",results.some(x=>x.group==="COLLABORATION"&&x.ok)?"LIVE QUERY":"ATTENTION"],["Social publishing OAuth","CONNECTOR NOT CONFIGURED"],["BERU AI model inference",results.find(x=>x.group==="AI")?.status||"NOT VERIFIED"],["End-user database",results.some(x=>x.group==="BERU AI"&&x.ok)?"LIVE QUERY":"ATTENTION"]].map(x=>'<div class="ent-platform"><strong>'+esc(x[0])+'</strong><small>'+esc(x[1])+'</small></div>').join("");
 const history=(health?.history||[]).slice(0,6);
 if(history.length){
  $("digitalSummary").innerHTML+='<div class="ent-item" style="display:block"><strong>Recent monitoring history</strong>'+history.map(x=>'<div style="display:flex;justify-content:space-between;gap:12px;padding:8px 0;border-top:1px solid #29243b"><span><b>'+esc(x.check_name)+'</b><small style="display:block">'+esc(x.checked_by_name)+' · '+esc(new Date(x.checked_at).toLocaleString())+'</small></span><span class="ent-pill">'+esc(x.status)+' · '+esc(x.latency_ms??"—")+' ms</span></div>').join("")+'</div>';
 }
 $("digitalLastCheck").textContent="Last check: "+(health?.checked_at?new Date(health.checked_at).toLocaleString():new Date().toLocaleString());
}
